<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $title }} · DancePro</title><style>:root{--brand:#0AA0DB;--ink:#141719;--muted:#66737a;--line:#d7e4ea;--danger:#b42318}*{box-sizing:border-box}body{display:grid;min-height:100vh;margin:0;padding:24px;place-items:center;background:linear-gradient(135deg,#101820,#1b2a35 50%,#0AA0DB 50%,#0AA0DB);font:14px/1.45 Arial,sans-serif}.auth-card{width:min(430px,100%);padding:26px;border:1px solid rgba(255,255,255,.55);border-radius:5px;background:rgba(255,255,255,.97);box-shadow:0 24px 70px rgba(16,24,32,.24)}h1{margin:0 0 8px;font-size:27px}p{color:var(--muted)}form,label{display:grid;gap:11px}label{gap:5px;color:var(--muted);font-size:12px;font-weight:700}input{min-height:43px;padding:9px 11px;border:1px solid var(--line);border-radius:4px;font:inherit}button{min-height:43px;border:0;border-radius:4px;background:var(--brand);color:white;font-weight:800;cursor:pointer}.message{margin-bottom:14px;padding:10px;border-radius:4px;background:#eaf8fd}.errors{margin-bottom:14px;padding:10px;border:1px solid #fecaca;border-radius:4px;background:#fff1f2;color:var(--danger)}a{color:#087fb0;text-align:center}</style></head><body><main class="auth-card">@if(session('status'))<div class="message">{{ session('status') }}</div>@endif @if($errors->any())<div class="errors">{{ $errors->first() }}</div>@endif @yield('content')</main></body></html>
